def min_sum_path(triangle):
    # Start from the second last row and move upwards
    for i in range(len(triangle) - 2, -1, -1):
        # Iterate through each element in the current row
        for j in range(len(triangle[i])):
            # Update the current element with the minimum of the current element and the sum of the two adjacent elements
            triangle[i][j] += min(triangle[i + 1][j], triangle[i + 1][j + 1])
    # The top element of the triangle will contain the minimum total path sum
    return triangle[0][0]

